(function () {
  var p = AutoJS.player();
  if (p === null) { return false; }
  var inv = p.getInventory();
  var size = Number(String(inv.getContainerSize()));
  var chips = 0, dice = false, medium = false, sign = false;
  for (var i = 0; i < size; i++) {
    var s = inv.getItem(i);
    if (s === null) { continue; }
    var id = String(AutoJS.id(s));
    if (id === 'astral_dice:abyss_reagent_chip') { chips = chips + Number(String(s.getCount())); }
    if (id === 'astral_dice:dice') { dice = true; }
    if (id === 'astral_dice:attack_card_medium') { medium = true; }
    if (id === 'astral_dice:jill_sign') { sign = true; }
  }
  var st = JSON.parse(AutoJS.state());
  var gm = String(st.gameMode).toLowerCase();
  var creative = (gm === 'creative');
  console.info('[REL150] ready chips=' + chips + ' dice=' + dice + ' medium=' + medium + ' sign=' + sign + ' gamemode=' + gm);
  return !!(creative && chips >= 3 && dice && medium && sign);
})()

(function () {
  var p = AutoJS.player();
  var st = JSON.parse(AutoJS.state());
  var inv = p.getInventory();
  var size = Number(String(inv.getContainerSize()));
  var slotted = 0, chips = 0, chipSlot = -1;
  for (var i = 0; i < size; i++) {
    var s = inv.getItem(i);
    if (s === null) { continue; }
    if (!s.isEmpty()) { slotted++; }
    if (String(AutoJS.id(s)) === 'astral_dice:abyss_reagent_chip') {
      chips = chips + Number(String(s.getCount()));
      if (chipSlot < 0 && i < 9) { chipSlot = i; }
    }
  }
  if (chipSlot >= 0) { inv.selected = chipSlot; }
  var heldId = String(AutoJS.id(AutoJS.held(p)));
  var pos = st.pos;
  var line = '[REL150] ver=fabric-1.20.1 gamemode=' + st.gameMode
    + ' pos=' + Math.floor(pos[0]) + ',' + Math.floor(pos[1]) + ',' + Math.floor(pos[2])
    + ' hp=' + Math.round(st.health)
    + ' food=' + st.food
    + ' xp=' + st.xpLevel
    + ' arm=' + st.armor
    + ' slotted=' + slotted
    + ' chips=' + chips
    + ' item=' + heldId
    + ' dim=' + st.dimension
    + ' modver=' + String(AutoJS.modVersion('astral_dice'));
  console.info(line);
  return line;
})()

(function () {
  var mc = Java.loadClass('net.minecraft.client.Minecraft').getInstance();
  var ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
  var Screen = Java.loadClass('net.minecraft.client.gui.screens.Screen');
  var Component = Java.loadClass('net.minecraft.network.chat.Component');
  var inv = mc.player.getInventory();
  var size = Number(String(inv.getContainerSize()));
  var count = 0, slot = -1, stack = null;
  for (var i = 0; i < size; i++) {
    var s = inv.getItem(i);
    if (s === null) { continue; }
    if (String(AutoJS.id(s)) === 'astral_dice:abyss_reagent_chip') {
      count = count + Number(String(s.getCount()));
      if (stack === null) { stack = s; slot = i; }
    }
  }
  var path = 'inventory';
  if (stack === null) {
    stack = new ItemStack(AutoJS.item('astral_dice:abyss_reagent_chip'));
    path = 'item-api';
  }
  var name = String(stack.getHoverName().getString());
  var lines = [];
  try {
    var tip = Screen.getTooltipFromItem(mc, stack);
    for (var j = 0; j < tip.size(); j++) { lines.push(String(tip.get(j).getString())); }
  } catch (e1) {
    path = path + '+hoverName';
    lines.push(name);
  }
  console.info('[REL150] chip id=astral_dice:abyss_reagent_chip count=' + count + ' name=' + name + ' tipn=' + lines.length + ' path=' + path + ' slot=' + slot);
  for (var k = 0; k < lines.length; k++) { console.info('[REL150] tip i=' + k + ' text=' + lines[k]); }
  var guide = String(Component.translatable('astral_dice.guide.entry.abyss_reagent_chip.1').getString());
  console.info('[REL150] guide key=astral_dice.guide.entry.abyss_reagent_chip.1 text=' + guide);
  return { ok: 1, id: 'astral_dice:abyss_reagent_chip', count: count, name: name, tipn: lines.length, path: path, slot: slot };
})()

(function () {
  var mc = Java.loadClass('net.minecraft.client.Minecraft').getInstance();
  var InvScreen = Java.loadClass('net.minecraft.client.gui.screens.inventory.InventoryScreen');
  var out = 'open=0 hover=skip';
  function findField(cls, name, maxUp) {
    var c = cls, d = 0;
    while (c !== null && d <= maxUp) {
      try { var f = c.getDeclaredField(name); f.setAccessible(true); return f; } catch (e) {}
      c = c.getSuperclass(); d = d + 1;
    }
    return null;
  }
  try {
    mc.setScreen(new InvScreen(mc.player));
    var scr = mc.screen;
    var CL = scr.getClass();
    var fl = findField(CL, 'leftPos', 3);
    var ft = findField(CL, 'topPos', 3);
    if (fl === null || ft === null) { throw new Error('leftPos/topPos not resolvable'); }
    var lx = Number(String(fl.getInt(scr)));
    var ty = Number(String(ft.getInt(scr)));
    var slots = scr.getMenu().slots;
    var target = null;
    for (var i = 0; i < slots.size(); i++) {
      var sl = slots.get(i);
      var st = sl.getItem();
      if (st === null) { continue; }
      if (st.isEmpty()) { continue; }
      if (String(AutoJS.id(st)) !== 'astral_dice:abyss_reagent_chip') { continue; }
      if (Number(String(sl.container.getContainerSize())) !== 41) { continue; }
      target = sl; break;
    }
    if (target === null) { throw new Error('chip slot not found in player inventory part'); }
    var x = lx + Number(String(target.x)) + 8;
    var y = ty + Number(String(target.y)) + 8;
    var win = mc.getWindow();
    var scale = Number(String(win.getScreenWidth())) / Number(String(win.getGuiScaledWidth()));
    var mh = mc.mouseHandler;
    var fx = findField(mh.getClass(), 'xpos', 2);
    var fy = findField(mh.getClass(), 'ypos', 2);
    if (fx !== null && fy !== null) {
      fx.setDouble(mh, x * scale);
      fy.setDouble(mh, y * scale);
    } else {
      out = 'open=0 hover=skip err=mouseHandler fields missing';
    }
    try { scr.mouseMoved(x, y); } catch (e4) {}
    out = 'open=1 hover=' + Math.round(x) + ',' + Math.round(y) + ' slot=' + Number(String(target.index)) + ' lx=' + lx + ' ty=' + ty + ' scale=' + scale + ' mh=' + Math.round(Number(String(fx.getDouble(mh)))) + ',' + Math.round(Number(String(fy.getDouble(mh))));
  } catch (e0) {
    out = 'open=0 hover=skip err=' + e0;
  }
  console.info('[REL150] inventory ' + out);
  return out;
})()

